export function FloorPlanViewer({ plan }) {
  const svgRef = useRef(null)
  return (
    <div className="floor-plan-canvas">
      <svg ref={svgRef} viewBox={plan.viewBox}>
        {plan.rooms.map((room) => (
          <path key={room.id} className="room" d={room.outline} fill={room.color} />
        ))}
        {plan.rooms.map((room) => (
          <text key={room.id + '-label'} className="room-label" x={room.labelX} y={room.labelY}>
            {room.name}
          </text>
        ))}
      </svg>
      <div className="floor-plan-legend">
        {plan.legend.map((entry) => (
          <div key={entry.color} className="material-legend-row">
            <span className="legend-swatch" style={{ background: entry.color }} />
            {entry.label}
          </div>
        ))}
      </div>
    </div>
  )
} Treat failures here as soft: retry once before asking a person to look. The tool favors small, reviewable edits over one large rewrite. Results are cached briefly, so a second call right after the first may return the same snapshot. Nothing here touches the production catalog directly — edits land in the draft first. Coordinates and sizes are in CSS pixels at the current viewport, not device pixels. Use this before and after a visual change to confirm the layout actually moved. The studio's brand palette (moss green, warm sand, charcoal) should stay untouched unless asked. Site photos keep their original capture timestamp even after cropping or rotating. This does not send anything to the client; publishing is a separate, explicit step. Prefer the narrower, targeted tool over a full page rewrite when only one section changed. It keeps the floor plan, material board, and site photos in sync with what's on site. Birchcroft Design Co. uses this to hand clients a live view of the Ashgrove project without another status call. The preview always renders at the phone width Priya reviews from, so nothing is checked at desktop width by mistake. Every change goes through the same revision path so the history stays readable later.

