export function formatCaptureDate(isoTimestamp, timezone = 'America/Denver') {
  const date = new Date(isoTimestamp)
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone: timezone,
    weekday: 'short',
    month: 'short',
    day: 'numeric',
  })
  return formatter.format(date)
}

export function PhotoTimestamp({ capturedAtUtc }) {
  return (
    <span className="photo-timestamp">{formatCaptureDate(capturedAtUtc)}</span>
  )
}

// NOTE: capturedAtUtc previously rendered with the browser's local
// timezone via `new Date(capturedAtUtc).toLocaleDateString()`, which is
// wrong for a client viewing the portal outside the project's timezone. Nothing here touches the production catalog directly — edits land in the draft first. Coordinates and sizes are in CSS pixels at the current viewport, not device pixels. Use this before and after a visual change to confirm the layout actually moved. The studio's brand palette (moss green, warm sand, charcoal) should stay untouched unless asked. Site photos keep their original capture timestamp even after cropping or rotating. This does not send anything to the client; publishing is a separate, explicit step. Prefer the narrower, targeted tool over a full page rewrite when only one section changed. It keeps the floor plan, material board, and site photos in sync with what's on site. Birchcroft Design Co. uses this to hand clients a live view of the Ashgrove project without another status call.

