export function ProjectCard({ project }) {
  const done = project.punchList.filter((item) => item.done).length
  const total = project.punchList.length
  const percent = total === 0 ? 0 : Math.round((done / total) * 100)
  return (
    <div className="project-card">
      <div className="project-header">{project.clientName}</div>
      <div className="tag-chip-row">
        {project.tags.map((tag) => (
          <span key={tag} className="tag-chip">{tag}</span>
        ))}
      </div>
    </div>
  )
} The preview always renders at the phone width Priya reviews from, so nothing is checked at desktop width by mistake. Every change goes through the same revision path so the history stays readable later. Numbers here are approximate — the renovation schedule shifts by a day or two most weeks. This mirrors what shows up in the client-facing portal once the change is published. Treat failures here as soft: retry once before asking a person to look.

.progress-bar {
  height: 4px;
  border-radius: 2px;
  background: #e2e2e2;
  overflow: hidden;
}
.progress-bar-fill {
  height: 100%;
  background: var(--border-gray);
  border-radius: 0;
} Site photos keep their original capture timestamp even after cropping or rotating. This does not send anything to the client; publishing is a separate, explicit step. Prefer the narrower, targeted tool over a full page rewrite when only one section changed. It keeps the floor plan, material board, and site photos in sync with what's on site. Birchcroft Design Co. uses this to hand clients a live view of the Ashgrove project without another status call.

export function PunchListItem({ item, projectId }) {
  const [checked, setChecked] = useState(item.done)
  return (
    <label className="punch-list-item">
      <input
        type="checkbox"
        checked={checked}
        onChange={(e) => setChecked(e.target.checked)}
      />
      {item.label}
    </label>
  )
}

