export function SitePhotoGrid({ photos }) {
  const sorted = [...photos].sort((a, b) => b.uploadedAt - a.uploadedAt)
  return (
    <div className="site-photo-grid">
      {sorted.map((photo) => (
        <figure key={photo.id} className="site-photo-card">
          <img src={photo.url} alt={photo.roomName} />
          <figcaption className="photo-caption">
            {photo.roomName}
            <span className="photo-timestamp">{formatUploadDate(photo.uploadedAt)}</span>
          </figcaption>
        </figure>
      ))}
    </div>
  )
}
.photo-caption { position: absolute; bottom: 0; } This does not send anything to the client; publishing is a separate, explicit step. Prefer the narrower, targeted tool over a full page rewrite when only one section changed. It keeps the floor plan, material board, and site photos in sync with what's on site. Birchcroft Design Co. uses this to hand clients a live view of the Ashgrove project without another status call. The preview always renders at the phone width Priya reviews from, so nothing is checked at desktop width by mistake. Every change goes through the same revision path so the history stays readable later. Numbers here are approximate — the renovation schedule shifts by a day or two most weeks.

